window.__FL_SRC=(window.__FL_SRC||"")+"s:end\"><div style=\"flex:1\"><input id=\"figureSearch\" value=\"${esc(q)}\" placeholder=\"이름, 구단, 국적, 역할 검색\" onkeydown=\"if(event.key==='Enter')UI.render_world(this.value)\"></div><button class=\"btn primary\" onclick=\"UI.render_world(document.getElementById('figureSearch').value)\">검색</button></div><div class=\"btnrow\">${types.map(t=>`<button class=\"btn ${UI.figureType===t?'primary':'secondary-active'}\" onclick=\"UI.render_world(document.getElementById('figureSearch')?.value||'', '${t}')\">${t}</button>`).join(\"\")}</div></div>\n      <div class=\"card c12\"><h2>🔎 관심 인물 / 관찰 목록</h2>${watched.length?`<div class=\"market-list\">${watched.map(f=>{const w=G.figureWatch?.[f.name]||{progress:0,lastUpdate:'관찰 대기'};return `<div class=\"offer\"><strong>${f.name}</strong><span class=\"muted\">${f.type} · ${f.club}</span><div class=\"statrow\"><span>관찰 진행도</span><b>${w.progress}%</b></div>${UI.bar(w.progress)}<p class=\"muted\">${w.lastUpdate}</p><div class=\"btnrow\"><button class=\"btn primary\" onclick=\"UI.openFigure('${f.name.replace(/'/g,\"\\'\")}')\">이력 / 리포트</button><button class=\"btn red\" onclick=\"Game.unobserveFigure('${f.name.replace(/'/g,\"\\'\")}')\">관찰 해제</button></div></div>`}).join(\"\")}</div>`:'<p class=\"muted\">관찰 중인 인물이 없습니다.</p>'}</div></div>\n      <div class=\"market-list\" style=\"margin-top:14px\">${figures.map(f=>`<div class=\"offer\"><strong>${f.name}</strong><span class=\"muted\">${f.type} · ${f.club}</span><div><span class=\"pill\">${f.nation}</span><span class=\"pill\">${f.era}</span></div><p>${f.summary}</p><div class=\"btnrow\"><button class=\"btn secondary-active\" onclick=\"UI.openFigure('${f.name.replace(/'/g,\"\\'\")}')\">이력 보기</button><button class=\"btn primary\" onclick=\"Game.observeFigure('${f.name.replace(/'/g,\"\\'\")}')\">관찰</button></div></div>`).join(\"\")||'<div class=\"card\" style=\"grid-column:1/-1\">검색 결과가 없습니다.</div>'}</div>\n      <div class=\"grid\"><div class=\"card c12\"><h2>축구계 뉴스</h2><div class=\"feed\">${G.worldNews.map(x=>`<div class=\"feed-item\">📰 ${esc(x)}</div>`).join(\"\")}</div></div></div>`;\n  },\n\n  render_legacy(){\n    const canRetire=G.stage===\"player\"&&G.age>=30;\n    document.getElementById(\"page-legacy\").innerHTML=UI.title(\"👑 은퇴 / 레거시\",\"선수 생활이 끝나도 게임은 계속됩니다.\")+(G.stage===\"player\"?`<div class=\"grid\"><div class=\"card c7\"><h2>현역 커리어</h2><p>현재 ${G.age}세 · ${G.club} · OVR ${G.ovr}</p><div class=\"stats-list\"><div class=\"statrow\"><span>통산 경기</span><b>${G.stats.apps}</b></div><div class=\"statrow\"><span>통산 골</span><b>${G.stats.goals}</b></div><div class=\"statrow\"><span>발롱도르</span><b>${G.awards.ballondor}</b></div><div class=\"statrow\"><span>트로피</span><b>${G.trophies.length}</b></div></div></div><div class=\"card c5\"><h2>은퇴 결정</h2><p class=\"muted\">${canRetire?\"지금 은퇴하면 은퇴 후 커리어를 바로 시작할 수 있습니다.\":\"30세부터 자발적 은퇴가 가능합니다.\"}</p><button class=\"btn ${canRetire?\"primary\":\"disabled\"}\" onclick=\"Game.retire()\">현역 은퇴 선언</button></div></div>`:`<div class=\"postcareer-banner\"><div class=\"eyebrow\">RETIREMENT</div><h2>${G.retirement.age}세 · ${G.retirement.year}년 은퇴</h2><p>${G.retirement.reason}</p></div><div class=\"career-grid\" style=\"margin-top:14px\">${DB.postCareers.map(p=>`<div class=\"career-option\"><div class=\"kpi\">${p.icon}</div><h2>${p.name}</h2><p class=\"muted\">${p.desc}</p><button class=\"btn ${G.postCareer.path===p.id?\"primary\":\"secondary-active\"}\" onclick=\"Game.choosePostCareer('${p.id}')\">${G.postCareer.path===p.id?\"현재 진로\":\"선택\"}</button></div>`).join(\"\")}</div><div class=\"grid\"><div class=\"card c6\"><h2>은퇴 후 상태</h2><div class=\"stats-list\"><div class=\"statrow\"><span>현재 진로</span><b>${G.postCareer.job||\"미선택\"}</b></div><div class=\"statrow\"><span>레벨</span><b>${G.postCareer.level}</b></div><div class=\"statrow\"><span>업계 평판</span><b>${G.postCareer.reputation}</b></div><div class=\"statrow\"><span>은퇴 후 경력</span><b>${G.postCareer.years.toFixed(1)}년</b></div></div>${UI.bar(G.postCareer.reputation)}</div><div class=\"card c6\"><h2>은퇴 후 행동</h2><div class=\"btnrow\"><button class=\"btn primary\" onclick=\"Game.postCareerAction('license')\">라이선스 / 전문성</button><button class=\"btn secondary-active\" onclick=\"Game.postCareerAction('network')\">축구계 네트워킹</button><button class=\"btn secondary-active\" onclick=\"Game.postCareerAction('venture')\">새 사업</button><button class=\"btn secondary-active\" onclick=\"Game.postCareerAction('academy')\">유소년 육성</button></div></div></div>`);\n  },\n\n  openProspect(id){const p=prospectById(id);if(!p)return;const t=G.scouting.targets[id]||{progress:0,status:\"미관찰\"};const scout=DB.scouts.find(s=>s.id===t.assigned);modal.classList.remove(\"hidden\");modalBody.innerHTML=`<div class=\"match-modal\"><div class=\"eyebrow\">SCOUT REPORT · ${p.pos}</div><h1>${p.name}</h1><p><span class=\"pill\">${p.age}세</span><span class=\"pill\">${p.nation}</span><span class=\"pill\">${p.club}</span></p><div class=\"grid\"><div class=\"card c6\"><h3>현재 평가</h3><div class=\"scout-head\"><div><small>OVR</small><b>${UI.scoutDisplay(p,'ovr')}</b></div><div><small>POT</small><b>${UI.scoutDisplay(p,'potential')}</b></div></div><div class=\"statrow\"><span>관찰 진행도</span><b>${t.progress||0}%</b></div>${UI.bar(t.progress||0)}<p class=\"muted\">${t.status||'미관찰'} · 담당 ${scout?.name||'미배정'}</p></div><div class=\"card c6\"><h3>능력치</h3><div class=\"attr-grid\">${Object.entries({pace:'스피드',shoot:'슈팅',pass:'패스',dribble:'드리블',defend:'수비',physical:'피지컬',vision:'시야',composure:'침착성'}).map(([k,n])=>`<div class=\"attr\"><span>${n}</span><b>${UI.scoutDisplay(p,k)}</b></div>`).join(\"\")}</div></div></div><div class=\"btnrow\"><button class=\"btn secondary-active\" onclick=\"UI.closeModal()\">닫기</button></div></div>`},\n  openFigure(name){const f=Game.getFigure(name);if(!f)return;const w=G.figureWatch?.[name]||{progress:0,lastUpdate:\"미관찰\"};const star=DB.stars.find(s=>s.name===name);const roleDetail=f.type.includes(\"감독\")?`전술 성향: ${f.style||\"데이터 없음\"}`:f.type===\"에이전트\"?`주요 고객군: ${(f.clients||[]).join(\", \")||\"비공개\"}`:star?`포지션 ${star.pos} · 게임 OVR ${star.ovr}`:`스타일: ${f.style||\"커리어 데이터 중심\"}`;modal.classList.remove(\"hidden\");modalBody.innerHTML=`<div class=\"match-modal\"><div class=\"eyebrow\">FOOTBALL DATABASE · ${f.type}</div><h1>${f.name}</h1><p><span class=\"pill\">${f.club}</span><span class=\"pill\">${f.nation}</span><span class=\"pill\">${f.era}</span></p><p>${f.summary}</p><div class=\"grid\"><div class=\"card c6\"><h3>프로필 / 관찰</h3><p>${roleDetail}</p><div class=\"statrow\"><span>관찰 진행도</span><b>${w.progress}%</b></div>${UI.bar(w.progress)}<p class=\"muted\">${w.lastUpdate}</p></div><div class=\"card c6\"><h3>주요 트로피</h3><div class=\"inventory\">${(f.trophies||[]).length?(f.trophies||[]).map(x=>`<span class=\"item-chip\">🏆 ${esc(x)}</span>`).join(\"\"):'<span class=\"muted\">등록된 트로피 정보 없음</span>'}</div></div><div class=\"card c6\"><h3>소속 / 경력</h3><div class=\"timeline\">${(f.clubs||f.history||[]).map(x=>`<div><strong>${esc(x)}</strong></div>`).join(\"\")}</div></div><div class=\"card c6\"><h3>주요 이력</h3><div class=\"timeline\">${(f.history||[]).map(x=>`<div><strong>${esc(x)}</strong></div>`).join(\"\")}</div></div></div><div class=\"btnrow\"><button class=\"btn primary\" onclick=\"Game.observeFigure('${f.name.replace(/'/g,\"\\'\")}')\">관찰 등록</button><button class=\"btn secondary-active\" onclick=\"UI.closeModal()\">닫기</button></div></div>`},\n  openMatch(){const m=G.pendingMatch;if(!m)return;modal.classList.remove(\"hidden\");modalBody.innerHTML=`<div class=\"match-modal\"><div class=\"eyebrow\">${m.comp} · ${m.starts?\"선발\":\"교체 출전\"}</div><h1>${G.club} vs ${m.opp}</h1><div class=\"match-scoreboard\"><div class=\"home\"><b>${G.club}</b></div><div class=\"bigscore\">${m.ourGoals} : ${m.oppGoals}</div><div class=\"away\"><b>${m.opp}</b></div></div><div class=\"match-clock\"><span>${m.minute}'</span><span>남은 결정 ${m.momentsLeft}</span><span>평점 ${m.rating.toFixed(1)}</span></div><div class=\"match-log\">${m.log.slice(-6).map(x=>`<div>${x}</div>`).join(\"\")}</div><h3>이번 장면에서 어떻게 할까?</h3><div class=\"action-grid\">${Game.matchActions().map(a=>`<button class=\"match-action\" onclick=\"Game.playMatchAction('${a.id}')\"><b>${a.name}</b><small>${a.sub}</small></button>`).join(\"\")}</div></div>`},\n  showMatchResult(r){modal.classList.remove(\"hidden\");const outcome=r.ourGoals>r.oppGoals?\"승리\":r.ourGoals<r.oppGoals?\"패배\":\"무승부\";modalBody.innerHTML=`<div class=\"result-hero\"><div class=\"eyebrow\">FULL TIME · ${outcome}</div><h2>${G.club} vs ${r.opp}</h2><div class=\"result-score\">${r.ourGoals} : ${r.oppGoals}</div><p>평점 <b>${r.rating.toFixed(1)}</b> · ${r.playerGoals}골 · ${r.playerAssists}도움</p><div class=\"match-log\">${r.log.slice(-8).map(x=>`<div>${x}</div>`).join(\"\")}</div><button class=\"btn primary\" onclick=\"Game.continueAfterMatch()\">경기 종료 · 다음 주로</button></div>`},\n  closeModal(){modal.classList.add(\"hidden\")},\n  toast(t){const el=document.createElement(\"div\");el.className=\"toast\";el.textContent=t;toast.appendChild(el);setTimeout(()=>el.remove(),2700)}\n};\n\nGame.init();\n";
